BEGIN;

-- Ficha de Vinicio Franco.
--
-- Campos: nombre legal Vinicio Antonio Franco Rodríguez (Wikipedia, Diario Libre);
-- aliases «Vinicio "Mambo" Franco» (Diario Libre, Wikipedia) y «El Príncipe del
-- Merengue» (El Nuevo Diario, Wikipedia); occupations musician (percusionista,
-- pianista, güirero: Diario Libre, Wikipedia).
--
-- Repertorio: 450 canciones (El Nuevo Diario) o 460 merengues (Diario Libre):
-- se escribió "más de 450".
-- Fuera: causa médica de la muerte, esposa e hijos.

UPDATE artists SET first_name = 'Vinicio', middle_name = 'Antonio', last_name = 'Franco', second_last_name = 'Rodríguez',
       aliases = ARRAY['Vinicio "Mambo" Franco', 'El Príncipe del Merengue']::text[], occupations = '["musician"]'::jsonb WHERE slug = 'vinicio-franco';

